application.css:
* { box-sizing: border-box; }

:root {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #263342;
  background: #f2f6f8;
}

body {
  min-height: 100vh;
  margin: 0;
  background: radial-gradient(circle at 15% 10%, #e2f4f2 0, transparent 34%), radial-gradient(circle at 90% 90%, #e8e8fb 0, transparent 35%), #f4f7f9;
}

.app-shell { width: min(100% - 32px, 650px); margin: 0 auto; padding: 8vh 0 28px; }
.todo-card { background: rgba(255,255,255,.94); border: 1px solid #e4eaee; border-radius: 24px; box-shadow: 0 20px 55px rgba(43, 62, 80, .11); padding: 34px; }
.app-header { display: flex; align-items: center; gap: 17px; margin-bottom: 30px; }
.brand-mark { display: grid; place-items: center; width: 54px; height: 54px; flex: 0 0 54px; border-radius: 16px; color: white; background: linear-gradient(145deg, #36b5a6, #278e9a); font-size: 28px; font-weight: 800; box-shadow: 0 8px 18px rgba(44, 158, 157, .25); }
.eyebrow { margin: 0 0 4px; color: #37a39b; font-size: 11px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
h1 { margin: 0; color: #1f2d3a; font-size: clamp(28px, 5vw, 37px); letter-spacing: -.045em; line-height: 1.05; }
.subtitle { margin: 7px 0 0; color: #84909a; font-size: 14px; }
.task-form { display: flex; gap: 10px; margin-bottom: 30px; }
.task-form input { min-width: 0; flex: 1; border: 1px solid #dce5e9; border-radius: 12px; outline: none; padding: 14px 16px; color: #263342; background: #fbfcfd; font: inherit; transition: .2s; }
.task-form input:focus { border-color: #49b5aa; box-shadow: 0 0 0 4px rgba(73,181,170,.13); }
.task-form button { border: 0; border-radius: 12px; padding: 0 20px; color: #fff; background: #2b9c98; font: inherit; font-weight: 750; cursor: pointer; transition: .2s; }
.task-form button:hover { background: #238783; transform: translateY(-1px); }
.list-heading { display: flex; align-items: center; justify-content: space-between; margin-bottom: 13px; }
h2 { margin: 0; color: #344452; font-size: 16px; }
.count-pill { border-radius: 20px; padding: 6px 11px; color: #488f8c; background: #e7f5f2; font-size: 12px; }
.count-pill strong { font-size: 13px; }
.task-list { display: grid; gap: 9px; }
.task { display: flex; align-items: center; gap: 12px; border: 1px solid #e8edef; border-radius: 13px; padding: 12px 13px; background: #fff; animation: appear .22s ease-out; }
.task-text { flex: 1; min-width: 0; overflow-wrap: anywhere; font-size: 15px; line-height: 1.4; }
.task[data-completed="true"] .task-text { color: #9aa5ad; text-decoration: line-through; }
.complete-button { display: grid; place-items: center; width: 22px; height: 22px; flex: 0 0 22px; border: 2px solid #c8d5d8; border-radius: 50%; color: #fff; background: white; cursor: pointer; }
.task[data-completed="true"] .complete-button { border-color: #35aaa0; background: #35aaa0; }
.complete-button::after { content: "✓"; opacity: 0; font-size: 13px; font-weight: 800; }
.task[data-completed="true"] .complete-button::after { opacity: 1; }
.delete-button { border: 0; padding: 5px; color: #aab4ba; background: transparent; cursor: pointer; font-size: 18px; line-height: 1; }
.delete-button:hover { color: #e16e70; }
.empty-state { padding: 35px 10px 22px; color: #9aa5ad; text-align: center; }
.empty-icon { display: grid; place-items: center; width: 38px; height: 38px; margin: 0 auto 10px; border-radius: 50%; color: #53b4ab; background: #e7f5f2; }
.empty-state p { margin: 0 0 4px; color: #64727d; font-size: 15px; font-weight: 700; }
.empty-state span { font-size: 13px; }
.page-note { margin: 18px 0 0; color: #99a5ad; font-size: 12px; text-align: center; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@keyframes appear { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: translateY(0); } }
@media (max-width: 480px) { .app-shell { width: min(100% - 20px, 650px); padding-top: 25px; } .todo-card { padding: 24px 18px; border-radius: 19px; } .task-form button { padding: 0 14px; } }

application.javascript:
const tasks = [];
const form = document.getElementById('task-form');
const input = document.getElementById('task-input');
const list = document.getElementById('task-list');
const emptyState = document.getElementById('empty-state');
const count = document.querySelector('[data-testid="incomplete-count"]');
const countLabel = document.getElementById('count-label');

function updateCount() {
  const remaining = tasks.filter(task => !task.completed).length;
  count.textContent = remaining;
  countLabel.textContent = remaining === 1 ? 'task left' : 'tasks left';
}

function render() {
  list.replaceChildren();
  tasks.forEach(task => {
    const item = document.createElement('div');
    item.className = 'task';
    item.dataset.testid = 'task';
    item.dataset.completed = String(task.completed);

    const complete = document.createElement('button');
    complete.type = 'button';
    complete.className = 'complete-button';
    complete.dataset.testid = 'task-complete';
    complete.setAttribute('aria-label', task.completed ? 'Mark task incomplete' : 'Mark task complete');
    complete.setAttribute('aria-pressed', String(task.completed));
    complete.addEventListener('click', () => {
      task.completed = !task.completed;
      render();
    });

    const text = document.createElement('span');
    text.className = 'task-text';
    text.dataset.testid = 'task-text';
    text.textContent = task.text;

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.dataset.testid = 'task-delete';
    remove.setAttribute('aria-label', `Delete task: ${task.text}`);
    remove.textContent = '×';
    remove.addEventListener('click', () => {
      const index = tasks.indexOf(task);
      if (index !== -1) tasks.splice(index, 1);
      render();
    });

    item.append(complete, text, remove);
    list.appendChild(item);
  });
  emptyState.hidden = tasks.length > 0;
  updateCount();
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const text = input.value.trim();
  if (!text) {
    input.focus();
    return;
  }
  tasks.push({ text, completed: false });
  input.value = '';
  render();
  input.focus();
});

render();

